// ===== Einstellungen =====
const MIN_LEVEL = 10;            // Minimales Wazuh-Alarm-Level
const DEFAULT_WINDOW_MIN = 60;   // Gleicher Alarm wird so viele Minuten nicht erneut gesendet
const RULE_WINDOW_MIN = {        // Eigene Sperrzeit pro Regel-ID (Minuten)
  '60602': 720,                  // Windows application error: max. alle 12 Stunden
};
const IGNORE_RULES = [];         // Regel-IDs, die nie gemeldet werden, z.B. ['60602']

// Speicher zwischen Ausfuehrungen (nur bei veroeffentlichtem Workflow, nicht bei manuellen Tests)
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const now = Date.now();
for (const k of Object.keys(store.seen)) {
  const e = store.seen[k];
  if (!e || typeof e !== 'object' || now - e.last_sent > 24 * 3600000) delete store.seen[k];
}

// Prueft, ob die IP oeffentlich ist (private/lokale IPs werden nicht an AbuseIPDB gesendet)
function isPublic(ip) {
  if (!ip) return false;
  ip = ip.replace(/^::ffff:/i, '');
  if (ip.includes(':')) {
    const l = ip.toLowerCase();
    return !(l === '::1' || l.startsWith('fe80') || l.startsWith('fc') || l.startsWith('fd'));
  }
  const p = ip.split('.').map(Number);
  if (p.length !== 4 || p.some(isNaN)) return false;
  if (p[0] === 10 || p[0] === 127 || p[0] === 0 || p[0] >= 224) return false;
  if (p[0] === 172 && p[1] >= 16 && p[1] <= 31) return false;
  if (p[0] === 192 && p[1] === 168) return false;
  if (p[0] === 169 && p[1] === 254) return false;
  if (p[0] === 100 && p[1] >= 64 && p[1] <= 127) return false;
  return true;
}

// Erster sinnvoller Wert aus mehreren moeglichen Feldern
function first(...vals) {
  for (const v of vals) {
    if (v !== undefined && v !== null && String(v).trim() !== '' && v !== '-') return String(v).trim();
  }
  return '';
}

// Windows-Ereignistext bereinigen und kuerzen
function cleanMsg(s, max = 450) {
  if (!s) return '';
  s = String(s).replace(/^"|"$/g, '').replace(/\\r|\\n|\r|\n|\\t|\t/g, ' ').replace(/\s{2,}/g, ' ').trim();
  return s.length > max ? s.slice(0, max) + ' ...' : s;
}

const out = [];
for (const item of $input.all()) {
  const a = item.json.body || item.json;
  const rule = a.rule || {};
  const agent = a.agent || {};
  const data = a.data || {};
  const win = data.win || {};
  const ev = win.eventdata || {};
  const sys = win.system || {};

  const level = Number(rule.level || 0);
  const ruleId = String(rule.id || '');
  if (level < MIN_LEVEL) continue;                 // Level zu niedrig -> ignorieren
  if (IGNORE_RULES.includes(ruleId)) continue;     // Regel steht auf der Ignorierliste

  // Angreifer-/Quell-IP aus Linux- und Windows-Feldern
  const srcip = first(data.srcip, data.src_ip, ev.ipAddress, ev.sourceAddress, ev.sourceNetworkAddress);

  // Duplikate unterdruecken und mitzaehlen
  const key = `${ruleId}|${agent.name}|${srcip}`;
  const windowMs = (RULE_WINDOW_MIN[ruleId] ?? DEFAULT_WINDOW_MIN) * 60000;
  const entry = store.seen[key];
  if (entry && now - entry.last_sent < windowMs) {
    entry.count = (entry.count || 0) + 1;
    continue;
  }
  const suppressed = entry ? (entry.count || 0) : 0;
  store.seen[key] = { last_sent: now, count: 0 };

  const mitre = rule.mitre || {};
  const actorUser = first(ev.subjectUserName);
  const actorDomain = first(ev.subjectDomainName);

  out.push({ json: {
    level,
    rule_id: ruleId,
    description: rule.description || '',
    groups: (rule.groups || []).join(', '),
    agent: agent.name || '',
    agent_ip: agent.ip || '',
    srcip,
    is_public_ip: isPublic(srcip),
    actor: actorUser ? (actorDomain ? `${actorDomain}\\${actorUser}` : actorUser) : first(data.srcuser),
    target: first(ev.targetUserName, data.dstuser),
    member: first(ev.memberName, ev.memberSid),
    workstation: first(ev.workstationName),
    event_id: first(sys.eventID),
    details: cleanMsg(first(sys.message, a.full_log)),
    mitre: (mitre.id || []).map((id, i) => `${id} ${(mitre.technique || [])[i] || ''}`.trim()).join(', '),
    mitre_tactic: (mitre.tactic || []).join(', '),
    location: a.location || '',
    timestamp: a.timestamp || '',
    window_min: windowMs / 60000,
    suppressed,
  }});
}
return out;

// Urspruengliche Alarmdaten und AbuseIPDB-Ergebnis zusammenfuehren
const a = $('Parse & Dedup').item.json;
const abuse = $json?.data || {};
const score = abuse.abuseConfidenceScore;
const crit = a.level >= 12 || (score !== undefined && score >= 90);   // Kritisch ab Level 12 oder AbuseIPDB >= 90 %

// Zeit in deutscher Ortszeit
let zeit = a.timestamp;
const d = new Date(String(a.timestamp).replace(/([+-]\d{2})(\d{2})$/, '$1:$2'));
if (!isNaN(d)) zeit = d.toLocaleString('de-DE', { timeZone: 'Europe/Berlin' });

const L = [];
L.push(`${crit ? '🔴 **CRITICAL**' : '🟠 **Warnung**'} — Wazuh Level ${a.level}`);
L.push(`**Regel:** ${a.description} (${a.rule_id})`);
if (a.details) L.push(`**Was ist passiert:** ${a.details}`);
L.push(`**Agent:** ${a.agent}${a.agent_ip ? ' (' + a.agent_ip + ')' : ''}`);

if (a.srcip) {
  let ip = `**Angreifer-/Quell-IP:** ${a.srcip}`;
  if (a.is_public_ip) {
    if (score !== undefined) {
      const extra = [abuse.countryCode, abuse.isp, abuse.totalReports !== undefined ? abuse.totalReports + ' Meldungen' : '']
        .filter(Boolean).join(', ');
      ip += ` — AbuseIPDB: ${score}%${extra ? ' (' + extra + ')' : ''}`;
    } else {
      ip += ' — AbuseIPDB: n/a';
    }
  } else {
    ip += ' (intern)';
  }
  L.push(ip);
}
if (a.actor)       L.push(`**Ausgeführt von:** ${a.actor}`);
if (a.target)      L.push(`**Betroffenes Konto/Gruppe:** ${a.target}`);
if (a.member)      L.push(`**Mitglied:** ${a.member}`);
if (a.workstation) L.push(`**Arbeitsstation:** ${a.workstation}`);
if (a.mitre)       L.push(`**MITRE ATT&CK:** ${a.mitre}${a.mitre_tactic ? ' — ' + a.mitre_tactic : ''}`);
if (a.event_id)    L.push(`**Event-ID:** ${a.event_id}`);
L.push(`**Zeit:** ${zeit}`);
if (a.suppressed > 0) L.push(`_ℹ️ ${a.suppressed} gleiche Alarme in den letzten ${a.window_min} Min. unterdrückt._`);

return { json: { ...a, abuse_score: score ?? null, message: L.join('\n') } };
